         secondsToTime(s) {
            //console.log( "msToTime:"+ s );
            if (Number.isNaN(s))
                return "NaN";
            else if ( s > 0 ) {
                let acertm = (min,hms) => { return (min > 9 ? min : (hms > 0 ? ("0" + min) : min)); }
                var secs = s % 60;
                s = (s - secs) / 60;
                var mins = s % 60;
                var hrs = (s - mins) / 60;

                //console.log( "return " + (hrs > 0 ? hrs + ':' : "") + acertm(mins,hrs) + ':' + acertm(secs,1));
                return (hrs > 0 ? hrs + ':' : "") + acertm(mins,hrs) + ':' + acertm(secs,1);
            } else return "0:0";
        }

        msToTime(s) {
            //console.log( "msToTime:"+ s );
            if (Number.isNaN(s))
                return "NaN";
            else if ( s > 0 ) {
                //let acertm = hms => { return (hms > 9 ? hms : ("0" + hms)); }
                var ms = s % 1000;
                s = (s - ms) / 1000;
                /*
                var secs = s % 60;
                s = (s - secs) / 60;
                var mins = s % 60;
                var hrs = (s - mins) / 60;
                */

                //return hrs + ':' + acertm(mins) + ':' + tm; // acertm(secs) /*+ '.' + ms*/;
                return this.secondsToTime(s); + '.' + ms;
            } else return "0:0";
        }



        timeToMs(str) {
            let stm = str.split(":");
            let tms = 0;
            switch( stm.length ) {
                case 3:
                    tms = parseInt(stm[0]) * 60 * 60;
                    stm = stm.slice(1);
                case 2:
                    tms += parseInt(stm[0]) * 60 + parseInt(stm[1]);
            }
            //console.log( "alarm in:" + tms );
            return tms * 1000;

        };

        randInt( tmin, tmax, mulTpl ) {
            if( (mulTpl || 0) > 0 ) { tmin *= mulTpl;tmax *= mulTpl;}
            return Math.round(Math.random() * (tmax - tmin)) + tmin;
        }

        ntostr( value, decp ) { return value.toLocaleString( undefined, { minimumFractionDigits: decp || 0 }); }
        strton( value ) { return Number(value.replaceAll(',','')); }

        //formatpt( nm, decp ) { return new Intl.NumberFormat('en-IN', { maximumSignificantDigits: decp || 0 }).format(nm);  }
        setsized ( instr, spt ) { return ( ("     " + instr).substring( -spt )); }

        valIfNull( test, pret )
        {
            let vret;
            if( test ) {
                vret = test;
            } else {
                if( (typeof(test) == "number" && test == 0) ||
                   (typeof(test) == "string" && test == "")
                  )
                    vret = test
                else
                    vret = pret;
            }

            return vret;
        }

