        objCompare(object1, object2) {
            const keys1 = Object.keys(object1);
            const keys2 = Object.keys(object2);
            if (keys1.length !== keys2.length) {
                return false;
            }
            for (let key of keys1) {
                if (object1[key] !== object2[key]) {
                    return false;
                }
            }
            return true;
        }

        objCompareNested(object1, object2) {
            let isObject = (object) => {
                return object != null && typeof object === 'object';
            }
            const keys1 = Object.keys(object1);
            const keys2 = Object.keys(object2);
            if (keys1.length !== keys2.length) {
                return false;
            }
            for (const key of keys1) {
                const val1 = object1[key];
                const val2 = object2[key];
                const areObjects = isObject(val1) && isObject(val2);
                if (
                    areObjects && !deepEqual(val1, val2) ||
                    !areObjects && val1 !== val2
                ) {
                    return false;
                }
            }
            return true;
        }


        createDOM = (element, options, content) => {
            let e = document.createElement(element);
            for (var key in options) {
                e.setAttribute(key, options[key]);
            }
            //if (content || content == 0) $(e).html(content);
            return e;
        }


    showDialog ( v_title, v_content, buttons, callback ) {

        let Dialogs = ( newDl, remove ) => {
            let index = null;
            this.dialogStats.forEach( (dx, indx) => {
                if( dx.title == newDl.title ) {
                    index = indx;
                    if( dx.timeout != null )
                        clearTimeout( dx.timeout );
                }
            });

            if ( index == null) {
                if ( !remove ) this.dialogStats.push( newDl );
            }
            else {
                this.dialogStats[ index ].ref.dialog('destroy').remove();
                if ( remove ) {
                    this.dialogStats.splice( index, 1);
                }
                else this.dialogStats[ index ] = newDl;
            }
        };

        let all_opp = [];
        let isClosed = false;
        let newDlset = { title : v_title, timeout : null };

        if( buttons != null ) {
            for ( let op = 0; op < buttons.length; ++ op ) {
                all_opp.push( { text: buttons[op].bTitle, class: "alert-button", height: 25, click: function(){

                    if( callback ) callback( {id:"CALLDATA", data: buttons[op].callBack || ""});

                    Dialogs( {title:v_title}, true );
                }});
            }
        }
        all_opp.push(
            { text: "Fechar", class: "alert-button", height: 25, click: function()
             {

                 if( callback ) {
                     callback( {id:"CANCEL"} );
                     //if (v_content != null) {if(v_content.cancel != null ) callback( v_title, {cancel:v_content.cancel}, true);}
                 }

                 isClosed = true;
                 Dialogs( {title:v_title}, true );
             }
            });

       
        let options = { modal: true };
        if( v_content != null ) {
            if(v_content.option) options = v_content.option;

            if( options ) {
                if( options.size ) {
                    v_content.text = $('<span style="font-size:' + options.size + 'px"></span>').append( v_content.text );
                }
            }
        }

        let masterDiv = $("<div></div>").append(v_content.text);
        let $dialog = masterDiv.dialog({
            autoOpen: false, title: v_title, modal: options.modal, width:(options.width || 'auto'), resizable: false, closeOnEscape: false, buttons: all_opp,
            close: function(event, ui)
            {
                isClosed = true;
                Dialogs( {title:v_title}, true );
            }
            //, classes: {"ui-dialog": "highlight"}
        });

        $dialog.dialog("open");
        if( v_content == null )
            $('.ui-dialog-content').hide();

        if( options.aclose > 0 ) {
            newDlset.timeout = setTimeout ( () => {
                if( !isClosed ) {
                    if( callback )
                        callback( {id:"TIMEOUT"});

                    $dialog.dialog("close");
                }
            }, options.aclose );
        }

        if( options.aClick ) {
            newDlset.timeout = setTimeout ( () => {
                if( callback )
                    callback( {id:"CALLDATA", data: buttons[options.aClick.button].callBack || ""});
            }, options.aClick.time );
        }

        $dialog.dialog({ closeText: ""});

        //$dialog.style.border="2px solid #0000FF";

        if( callback ) callback( {id:"INIT"});


        newDlset.ref = $dialog;
        Dialogs( newDlset, false );
        return $dialog;
    }
    
